#[test]
fn d842_glibc_pow_bitwise_sample() {
    let mut bad = 0u32;
    let mut first = None;
    for (n, (xb, yb, rb)) in POW_TRIPLES.iter().enumerate() {
        let (x, y) = (f64::from_bits(*xb), f64::from_bits(*yb));
        let got = glibc_pow(x, y).to_bits();
        if got != *rb {
            bad += 1;
            if first.is_none() { first = Some((n, x, y)); }
        }
    }
    assert_eq!(bad, 0, "glibc_pow sample mismatches: {first:?}");
}

#[test]
fn d842_glibc_hypot_bitwise_sample() {
    let mut bad = 0u32;
    let mut first = None;
    for (n, (xb, yb, rb)) in HYPOT_TRIPLES.iter().enumerate() {
        let (x, y) = (f64::from_bits(*xb), f64::from_bits(*yb));
        let got = glibc_hypot(x, y).to_bits();
        if got != *rb {
            bad += 1;
            if first.is_none() { first = Some((n, x, y)); }
        }
    }
    assert_eq!(bad, 0, "glibc_hypot sample mismatches: {first:?}");
}
